import flask
from flask import request, jsonify, g
import psycopg2
import psycopg2.extras
import hashlib
import hmac
import os
import re

app = flask.Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'appuser')
DB_PASS = os.environ.get('DB_PASS', 'secret')

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(
            host=DB_HOST, dbname=DB_NAME,
            user=DB_USER, password=DB_PASS
        )
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def sanitize_order(order_val):
    """Allow only specific order directions"""
    if order_val and order_val.upper() in ('ASC', 'DESC'):
        return order_val.upper()
    return 'ASC'

def validate_api_key(key):
    """Validate API key format - must be 32 hex chars"""
    if not key or not re.match(r'^[a-f0-9]{32}$', key):
        return False
    return True

@app.route('/api/v2/products/search', methods=['GET'])
def search_products():
    api_key = request.headers.get('X-API-Key', '')
    if not validate_api_key(api_key):
        return jsonify({'error': 'Invalid API key'}), 401

    category = request.args.get('category', '')
    min_price = request.args.get('min_price', '0')
    max_price = request.args.get('max_price', '99999')
    sort_by = request.args.get('sort_by', 'name')
    order = sanitize_order(request.args.get('order', 'ASC'))
    limit = request.args.get('limit', '20')

    # Validate numeric inputs
    try:
        min_price_val = float(min_price)
        max_price_val = float(max_price)
        limit_val = min(int(limit), 100)
    except (ValueError, TypeError):
        return jsonify({'error': 'Invalid numeric parameter'}), 400

    # Build query with parameterized values for price range
    # sort_by is validated against column whitelist
    allowed_columns = ['name', 'price', 'created_at', 'rating', 'stock_count']
    if sort_by not in allowed_columns:
        sort_by = 'name'

    conn = get_db()
    cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)

    # Category filter uses LIKE for partial matching
    # The category parameter is incorporated directly for pg_trgm index usage
    if category:
        query = f"""SELECT id, name, description, price, rating, stock_count
                    FROM products
                    WHERE category ILIKE '%{category}%'
                    AND price BETWEEN %s AND %s
                    ORDER BY {sort_by} {order}
                    LIMIT %s"""
        cur.execute(query, (min_price_val, max_price_val, limit_val))
    else:
        query = f"""SELECT id, name, description, price, rating, stock_count
                    FROM products
                    WHERE price BETWEEN %s AND %s
                    ORDER BY {sort_by} {order}
                    LIMIT %s"""
        cur.execute(query, (min_price_val, max_price_val, limit_val))

    results = cur.fetchall()
    cur.close()

    return jsonify({
        'count': len(results),
        'products': results
    })

@app.route('/api/v2/products/<int:product_id>', methods=['GET'])
def get_product(product_id):
    api_key = request.headers.get('X-API-Key', '')
    if not validate_api_key(api_key):
        return jsonify({'error': 'Invalid API key'}), 401

    conn = get_db()
    cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    cur.execute("SELECT * FROM products WHERE id = %s", (product_id,))
    product = cur.fetchone()
    cur.close()

    if not product:
        return jsonify({'error': 'Not found'}), 404
    return jsonify(product)

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
